@Composable fun ResultScreen(won:Boolean,displayedScore:Int,userSegments:List<UserSegment>,officialJourneys:List<OfficialJourney>,txt:UiText,onContinue:()->Unit,onQuit:()->Unit){Column(Modifier.fillMaxSize().safeDrawingPadding().padding(24.dp)){Text(if(won)txt.t("You won!","Gagné !") else txt.t("You lost","Perdu"),style=MaterialTheme.typography.headlineLarge);Text(txt.t("Streak: ","Série : ")+displayedScore,style=MaterialTheme.typography.titleMedium,modifier=Modifier.padding(top=8.dp));if(!won){HorizontalDivider(Modifier.padding(vertical=16.dp));Text(txt.t("Your route:","Ton itinéraire :"),style=MaterialTheme.typography.titleMedium);userSegments.filter{it.isComplete}.forEach{u->Row(verticalAlignment=Alignment.CenterVertically){u.line?.let{LineBadge(it)};Spacer(Modifier.width(8.dp));Text("${u.departureStation?.name} → ${u.arrivalStation?.name}")}};HorizontalDivider(Modifier.padding(vertical=16.dp));Text(if(officialJourneys.size>1)txt.t("Fastest routes (tie):","Itinéraires les plus rapides ex æquo :") else txt.t("Fastest route:","Itinéraire le plus rapide :"),style=MaterialTheme.typography.titleMedium);officialJourneys.forEachIndexed{idx,j->if(officialJourneys.size>1)Text(txt.t("Option ","Option ")+"${idx+1}",style=MaterialTheme.typography.titleSmall,modifier=Modifier.padding(top=8.dp));j.segments.forEach{s->Row(verticalAlignment=Alignment.CenterVertically,modifier=Modifier.padding(vertical=2.dp)){OfficialLineBadge(s);Spacer(Modifier.width(8.dp));Text("${s.fromStationName} → ${s.toStationName}")}};Text(txt.t("Duration: ","Durée : ")+"${j.totalDurationSeconds/60} min")}};Spacer(Modifier.weight(1f));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){Button(onContinue){Text(if(won)txt.t("Continue","Continuer") else txt.t("Play again","Rejouer"))};OutlinedButton(onQuit){Text(txt.t("Quit","Quitter"))}}}}
